# 부분 장애 예시: Python 3에서 실행 가능한 코드
services = {"api": "ok", "search": "slow", "billing": "down"}
print([k for k, v in services.items() if v != "ok"])

# 분산 트랜잭션 예시: Python 3에서 실행 가능한 코드
steps = {"flight": True, "hotel": True}
print("success" if all(steps.values()) else "compensate")

# CRDT(충돌 없는 복제 자료형) 예시: Python 3에서 실행 가능한 코드
a = {"x", "y"}
b = {"y", "z"}
merged = a | b
print(merged)

# 반엔트로피 예시: Python 3에서 실행 가능한 코드
a = {"x": 1, "y": 2}
b = {"x": 1}
missing = set(a) - set(b)
print(missing)

# 가십 프로토콜 예시: Python 3에서 실행 가능한 코드
known = {"n1": {"a"}}
known["n2"] = known["n1"] | {"b"}
print(known["n2"])

# 분산 파일 시스템 예시: Python 3에서 실행 가능한 코드
blocks = {"file1": ["n1:block0", "n2:block1"]}
print(blocks["file1"])

# 오브젝트 스토리지 아키텍처 예시: Python 3에서 실행 가능한 코드
obj = {"key": "photos/1.jpg", "metadata": {"type": "image"}}
print(obj["key"])

# 캐시 일관성 프로토콜 예시: Python 3에서 실행 가능한 코드
caches = {"a": 1, "b": 1}
new_value = 2
caches = {k: new_value for k in caches}
print(caches)

# Compaction 예시: Python 3에서 실행 가능한 코드
files = [{"a": 1}, {"a": 2, "b": 3}]
merged = {}
for f in files: merged.update(f)
print(merged)

# 분산 메시지 큐 설계 예시: Python 3에서 실행 가능한 코드
partitions = {0: ["m1"], 1: ["m2"]}
print(sum(len(v) for v in partitions.values()))

# 소비자 그룹 예시: Python 3에서 실행 가능한 코드
group = {"c1": [0, 2], "c2": [1, 3]}
print(group["c1"])

# 벌크헤드 패턴 예시: Python 3에서 실행 가능한 코드
pools = {"search": 10, "payment": 5}
print(pools["payment"])

# 멀티 리전 복제 예시: Python 3에서 실행 가능한 코드
replicas = {"seoul": 10, "tokyo": 10}
print(len(set(replicas.values())) == 1)

# P2P 네트워크 기초 예시: Python 3에서 실행 가능한 코드
peers = {"p1": ["p2"], "p2": ["p1", "p3"]}
print(peers["p2"])

# 분산 스냅샷 예시: Python 3에서 실행 가능한 코드
state = {"n1": 5, "n2": 7, "in_flight": 2}
print(sum(state.values()))

# 체크포인트(분산) 예시: Python 3에서 실행 가능한 코드
checkpoint = {"step": 100, "state": "saved"}
print(checkpoint["step"])

# 데이터 복제 전략 예시: Python 3에서 실행 가능한 코드
strategy = {"replicas": 3, "regions": 2, "sync": False}
print(strategy)
